create or replace function private.audit_operational() returns trigger language plpgsql security definer set search_path='' as $$ declare prev jsonb; nxt jsonb; area text; begin if TG_OP='UPDATE' then prev=to_jsonb(old);end if;nxt=to_jsonb(new);area=case when TG_TABLE_NAME in ('sales_channels','sales_fee_rules','sales_orders','sales_items','sale_receipts','business_goals','alert_resolutions','purchase_financial_links') then 'financial' else 'operational' end;insert into public.audit_logs(organization_id,user_id,action,entity,entity_id,domain,old_value,new_value) values((nxt->>'organization_id')::uuid,auth.uid(),TG_OP,TG_TABLE_NAME,nxt->>'id',area,prev,nxt);return new;end $$;revoke all on function private.audit_operational() from public,anon,authenticated;
